from expand_a_common import *
d='p2-t1-d04'
item(d,15,'Vibe check ở giai đoạn prototype nhằm mục đích chính nào?', ['Khám phá hành vi, failure modes và đầu ra tốt trước khi đặc tả chi tiết','Công bố điểm benchmark chính thức thay cho offline eval','Chốt release chỉ từ một demo thành công'],'a','Quan sát model chạy giúp xác định giới hạn và yêu cầu sản phẩm thực tế.')
item(d,16,'Golden outputs có thể được sử dụng vào những việc nào? (Chọn tất cả đáp án đúng.)',['Làm reference cho evals','Làm ví dụ few-shot','Thay mọi kiểm tra production vì đã có output mẫu','Buộc model đoán khi input thiếu thông tin'],['a','b'],'Đầu ra đạt kỳ vọng tạo chuẩn tham chiếu; dataset vẫn cần edge cases và tiếp tục lớn lên.')
item(d,17,'Sau một prompt change làm regression, quy trình xử lý phù hợp là gì?', ['Điều tra, sửa rồi chạy lại toàn bộ eval trên reference dataset','Chỉ chạy lại case vừa fail và bỏ baseline','Đổi threshold để phiên bản mới được pass ngay'],'a','Cùng dataset/baseline giúp nhận diện regression; sửa một case không bảo đảm các case khác còn tốt.')
item(d,19,'Offline score tốt nhưng online quality giảm thường là tín hiệu cần kiểm tra điều gì?', ['Dataset có phản ánh input và hành vi production hiện tại không','Có thể ngừng monitor vì offline score đã cao','Chỉ tăng số happy-path paraphrases trong dataset'],'a','Khoảng cách phân bố hoặc tình huống mới có thể làm offline eval không đại diện thực tế.')
item(d,23,'“Cải thiện hỗ trợ khách hàng bằng AI” cần được thu hẹp thế nào để đánh giá được?', ['Xác định task, điều kiện input và mức tự chủ thành một đơn vị công việc có rubric rõ','Chỉ đổi thành “AI hỗ trợ tốt hơn” để giữ mục tiêu linh hoạt','Tăng số người chấm mà giữ nguyên tiêu chí mơ hồ'],'a','Một unit cụ thể cho phép hai người chấm độc lập đi đến cùng kết luận pass/fail.')
item(d,25,'Vì sao 50 test inputs chưa chắc có coverage tốt hơn 20 inputs?', ['Nhiều inputs có thể chỉ là bản diễn đạt lại của vài trường hợp','Số rows luôn tỷ lệ thuận với số failure modes được bao phủ','Dataset nhỏ hơn tự động có nhiều edge cases hơn'],'a','Coverage phụ thuộc trường hợp hành vi và điều kiện được chọn, không chỉ số lượng rows.')
item(d,26,'Một thuộc tính input đáng làm dimension của test grid khi nào?', ['Đổi giá trị thuộc tính làm expected behavior đúng thay đổi','Chỉ đổi cách diễn đạt nhưng agent vẫn phải làm cùng hành động','Thuộc tính dễ sinh nhiều paraphrases nhất'],'a','Dimension cần tạo đa dạng có ý nghĩa cho hành vi, như đủ thông tin so với thiếu mã đơn.')
item(d,29,'Trong quy trình thiết kế test grid, AI nên hỗ trợ vai trò nào?', ['Diễn đạt lại các scenarios do con người kiểm soát coverage','Tự chọn toàn bộ coverage thay cho quyết định sản phẩm','Tạo nhiều rows trước rồi xem số lượng là coverage'],'a','Human chọn dimensions/combinations quan trọng; LLM hỗ trợ biến scenario thành cách hỏi tự nhiên.')
item(d,30,'Vì sao pass rate trên challenge set không thể được coi trực tiếp là production success rate?', ['Challenge set cố ý lấy nhiều tình huống khó hơn tỷ trọng tự nhiên','Mọi challenge case đều không xuất hiện trong production','Chỉ cần tăng sample size là loại bỏ khác biệt phân bố'],'a','Over-sampling tình huống khó phục vụ khám phá lỗi nhưng không đại diện tỷ lệ lưu lượng thật.')
item(d,32,'Agent nói “đã đặt vé” chưa đủ chứng minh task hoàn tất. Bằng chứng nào cần kiểm tra?', ['Tool call/tham số và reservation thật trong trạng thái cuối','Chỉ độ tự tin trong câu trả lời cuối','Chỉ việc response không có lỗi ngữ pháp'],'a','Transcript là lời kể; trace và state cho thấy hành động thực sự được thực hiện.')
item(d,35,'Chuẩn hóa ghi chú lỗi thành trace codes hỗ trợ điều gì?', ['Đo, so sánh và sửa cùng một loại failure bằng ngôn ngữ chung','Giữ mỗi người đặt tên khác nhau để có nhiều nhãn hơn','Loại bỏ nhu cầu xem các trace cụ thể đằng sau nhãn'],'a','Taxonomy thống nhất nối quan sát tự do với phân tích có thể tổng hợp và hành động.')
item(d,39,'Agent chưa bao giờ gửi được lịch vì Calendar API chưa được kết nối. Nên ưu tiên gì?', ['Sửa năng lực/tích hợp hệ thống','Chỉ viết thêm automated eval cho tính nhất quán','Chỉ thêm ví dụ vào judge prompt để tăng pass rate'],'a','Đây là architectural gap, khác việc có lúc làm được nhưng thiếu khả năng generalize ổn định.')
item(d,40,'Những tiêu chí nào phù hợp kiểm tra bằng code trước khi dùng LLM judge? (Chọn tất cả đáp án đúng.)',['Trường bắt buộc và schema output','Có gọi đúng tool hay không','Cảm nhận brand voice tinh tế trong ngữ cảnh mở','Tính thuyết phục tùy người đọc'],['a','b'],'Rule rõ và có thể kiểm deterministic nên dùng code; sắc thái/ngữ cảnh thường cần cách khác.')
item(d,41,'Khi tiêu chí không có referent kiểm chứng độc lập ngoài phán đoán con người, AI nên hỗ trợ thế nào?', ['Trích dữ kiện/bằng chứng để người quyết định','Xuất điểm số tự động như kết luận cuối','Dùng confidence của chính model làm chuẩn đúng'],'a','Không có referent thì AI hỗ trợ giảm công kiểm tra, không thay người phán quyết bằng số tự sinh.')
item(d,47,'Một eval bỗng có pass rate 0% nhưng spot check output có vẻ ổn. Nên kiểm tra gì trước?', ['Regex, field và logic evaluator','Kết luận agent hoàn toàn mất năng lực','Bỏ toàn bộ reference labels để khôi phục pass rate'],'a','Evaluator có thể sai; cần kiểm chính phép đo trước khi quy nguyên nhân cho agent.')
item(d,49,'Vì sao threshold release cần được chốt trước khi iterate?', ['Tránh thương lượng tiêu chuẩn theo kết quả vừa quan sát','Để luôn hạ threshold nếu model mới kém baseline','Để thay regression test bằng cảm giác demo'],'a','Một gate chỉ có ý nghĩa khi chuẩn được định trước và mọi thay đổi đi qua cùng phép kiểm.')
item(d,53,'Human và judge đều cho 70% Pass. Có thể kết luận judge đã calibrate chưa?', ['Chưa; cần so verdict từng case và loại sai lệch','Có; cùng tổng pass rate nghĩa là cùng quyết định mọi case','Có; chỉ cần judge trả reasoning dài và rõ'],'a','Cùng tổng tỷ lệ có thể che cả bỏ lọt output xấu lẫn chặn nhầm output tốt.')
d='p2-t1-d05'
item(d,7,'Trong AI tuyển dụng, quyền human review và override cần được xác định để giải quyết nhu cầu nào?', ['Có người có thẩm quyền kiểm tra và bác quyết định tự động','Bảo đảm mọi điểm số model đều thành quyết định cuối','Chỉ đo shortlist tổng mà không xét người bị loại'],'a','Quyền bác quyết định và trách nhiệm rõ tạo khả năng can thiệp vào workflow thực.')
item(d,8,'Một AI tutor giúp ra đáp án nhanh nhưng khiến sinh viên phụ thuộc hơn. Câu hỏi sản phẩm cần đánh giá là gì?', ['Cách hỗ trợ có thúc đẩy hiểu và tự suy nghĩ hay làm tăng lệ thuộc?','Chỉ response có đúng format để gửi cho sinh viên không','Chỉ tốc độ sinh đáp án có cao hơn bản trước không'],'a','Mục tiêu học tập cần xét tác động lên năng lực người học, không chỉ output đúng và nhanh.')
item(d,9,'Đánh giá safety của sản phẩm AI cần gắn kết quả kỹ thuật với điều gì?', ['Ai chịu tác động, trong ngữ cảnh nào và bằng chứng đủ để triển khai','Chỉ benchmark của model nền độc lập với ứng dụng','Chỉ mức hài lòng của nhóm phát triển về demo'],'a','Safety là tính chất trong sử dụng thực với người và hậu quả cụ thể.')
item(d,13,'Quan hệ nào mô tả đúng model và AI system?', ['Model là một phần của hệ thống có cả giao diện và hạ tầng','Model weights bao gồm mọi quyết định UX và workflow triển khai','Cải thiện model tự động giải quyết mọi lỗi ở lớp system'],'a','Lỗi có thể xuất phát ở các thành phần quanh model, không chỉ weights hoặc thuật toán.')
item(d,14,'Ngoài thành phần kỹ thuật, phân tích tác động AI cần xét những yếu tố nào? (Chọn tất cả đáp án đúng.)',['Bối cảnh văn hóa, quản trị và ứng dụng','Những người chịu ảnh hưởng hoặc có quyền tác động','Chỉ người trực tiếp đăng nhập hệ thống','Chỉ tên model và kích thước weights'],['a','b'],'Bối cảnh sử dụng và stakeholder mở rộng cho thấy ảnh hưởng vượt người vận hành trực tiếp.')
item(d,15,'Tổ hợp nào phản ánh việc triển khai AI an toàn hơn?', ['Bối cảnh phù hợp, guardrails và người chịu trách nhiệm','Model có benchmark cao nên không cần owner xử lý sự cố','Có cảnh báo chung nên không cần thiết kế escalation'],'a','Safety cần cả cơ chế kiểm soát lẫn accountability trong ứng dụng cụ thể.')
item(d,17,'Hệ thống tối ưu đúng mục tiêu thiết kế có thể vẫn gây harm không?', ['Có, vì mục tiêu tối ưu có thể xung đột với lợi ích con người và xã hội','Không, harm chỉ xảy ra khi code sai đặc tả','Không, nếu metric kinh doanh đang tăng thì tác động đã tốt'],'a','Đạt mục tiêu kỹ thuật không tự chứng minh mục tiêu và hậu quả là phù hợp.')
item(d,19,'Việc dùng dữ liệu cá nhân để dựng narrative gây hại dù có điều khoản dài cần đặt câu hỏi nào?', ['Người dùng có đồng thuận thực chất và quyền kiểm soát hình ảnh/câu chuyện của mình không?','Chỉ việc nội dung có tăng tương tác đúng mục tiêu không','Chỉ việc dữ liệu có đủ lớn để cá nhân hóa không'],'a','Một chấp thuận trên giấy không tự bảo đảm quyền kiểm soát và phẩm giá trong việc tái sử dụng dữ liệu.')
item(d,22,'Khi xây thư viện test cho hệ thống tự lái trong operational domain, tình huống hiếm có thể dẫn đến va chạm nên được xử lý thế nào?', ['Đưa vào test dù tần suất thấp','Bỏ qua vì chỉ cần bao phủ tình huống trung bình','Chỉ test sau khi có nhiều va chạm thực tế'],'a','Mức hậu quả và tính liên quan tới phạm vi vận hành khiến edge/corner cases vẫn cần kiểm thử.')
item(d,23,'AI đồng ý với nhận định sai của người dùng sau khi bị thúc ép đang biểu hiện failure mode nào?', ['Sycophancy','Privacy leak do xuất dữ liệu không được phép','Escalation failure vì thiếu kênh chuyển người'],'a','Sycophancy là chiều theo người dùng dù nhận định của họ sai.')
item(d,23,'Người dùng xem output AI như quyết định cuối rồi ngừng kiểm tra đang gặp rủi ro nào?', ['Over-reliance','Grounding tốt vì user tin response','Jailbreak vì user cố vượt policy'],'a','Tin quá mức có thể do cách nói chắc chắn hoặc UX tạo cảm giác chính thức, khác cố ý lạm dụng.')
item(d,23,'Bot tiếp tục tự xử lý một trường hợp đã vượt thẩm quyền thay vì handoff đang mắc lỗi nào?', ['Escalation failure','Chỉ lỗi tone dù workflow vẫn đúng','Chỉ dữ liệu lệch giữa các nhóm'],'a','Thiếu rule/handoff/fallback có thể giữ AI ở quyết định cần người có trách nhiệm.')
item(d,24,'Bot HR trả lời chính sách nghỉ phép từ handbook cũ. Layer nào nên kiểm tra trước?', ['Grounding và nguồn dữ liệu được dùng','Chỉ UX của nút gửi câu hỏi','Chỉ safety refusal dù câu hỏi hợp lệ'],'a','Dữ liệu chuẩn không cập nhật khiến model có thể trả lời sai ngay cả khi diễn đạt tốt.')
item(d,24,'Giao diện trình bày câu trả lời bot như quyết định chính thức và không có đường xem nguồn làm tăng rủi ro nào?', ['Người dùng tin quá mức do UX che giới hạn và cơ sở thông tin','Chỉ model bị thiếu context window cho câu hỏi dài','Chỉ tool timeout trong lúc thực thi'],'a','Lớp UX có thể khiến người dùng đánh giá sai độ chắc chắn và bỏ qua kiểm chứng.')
item(d,25,'Sau khi xác định failure mode và layer khởi phát, harm map cần làm rõ điều gì?', ['Ai bị ảnh hưởng và hậu quả cụ thể có thể xảy ra','Chỉ tên lỗi kỹ thuật để kết thúc phân tích','Chỉ severity chung mà không mô tả sự kiện'],'a','Harm cần diễn tả tác động thật như mất cơ hội, tiền, quyền riêng tư hay phẩm giá.')
item(d,26,'Một lần rò dữ liệu nhạy cảm hiếm gặp vẫn có thể cần ưu tiên cao vì sao?', ['Hậu quả khó thu hồi và phạm vi ảnh hưởng có thể lớn','Tần suất thấp luôn đồng nghĩa severity thấp','Chỉ lỗi thường xuyên mới tạo tác động thực'],'a','Đánh giá cần tách tần suất, xác suất, mức nghiêm trọng và scale thay vì dùng một trục duy nhất.')
item(d,29,'Những thông tin nào giúp biến một compliance gap thành việc có thể quản lý trong roadmap? (Chọn tất cả đáp án đúng.)',['Requirement và current/required state','Owner, deadline và trạng thái','Evidence, monitoring và re-test','Một cam kết chung không có người chịu trách nhiệm'],['a','b','c'],'Action plan cần nối gap với hành động và bằng chứng hoàn thành, không chỉ tuyên bố tuân thủ.')
d='p2-t1-d06'
item(d,4,'Activation khác một lần đăng nhập ở điểm nào?', ['Người dùng lần đầu thực sự nhận được giá trị','Chỉ cần tạo tài khoản dù chưa làm việc chính','Chỉ cần nằm trong danh sách MAU'],'a','Activation gắn với first value, không phải mọi hành vi truy cập.')
item(d,4,'Time to Value đo khoảng thời gian nào?', ['Từ khi vào sản phẩm đến giá trị đầu tiên','Từ giá trị đầu tiên đến lúc churn','Từ thanh toán lần đầu đến khi thu hồi CAC'],'a','TTV phản ánh tốc độ đạt giá trị ban đầu, khác vòng đời và payback.')
item(d,7,'Tăng số vị trí quảng cáo có thể tăng revenue/user nhưng giảm engagement. Vì sao cần tradeoff metric?', ['Để thấy tổn hại của tối ưu một chỉ số lên giá trị khác','Để mọi input metric tăng đều được coi là thành công','Để bỏ qua engagement khi doanh thu ngắn hạn tăng'],'a','Một thay đổi có thể tác động trái chiều lên nhiều mục tiêu cần được theo dõi cùng nhau.')
item(d,15,'Vì sao MAU tăng chưa chứng minh retention tốt?', ['Acquisition/hype có thể bù người rời đi và một lần vào trong tháng vẫn được tính','MAU chỉ đếm người dùng quay lại mỗi ngày','Mọi tăng trưởng MAU đều đến từ cùng cohort được giữ lại'],'a','Chỉ số tổng gộp che chuyển động cohort và mức sử dụng lặp lại.')
item(d,16,'Những cơ chế nào giải thích giá trị kinh doanh của retention? (Chọn tất cả đáp án đúng.)',['Tăng cơ hội referral/content và acquisition loops','Người dùng ở lại có thêm thời gian mua và trả tiền','Có thể cải thiện economics và tái đầu tư tăng trưởng','Tự loại bỏ nhu cầu tạo core value cho user'],['a','b','c'],'Giữ người dùng có giá trị nối việc sử dụng dài hạn với phân phối và monetization.')
item(d,17,'Retention và engagement trả lời hai câu hỏi khác nhau như thế nào?', ['Ai còn quay lại theo thời gian, và những người đó dùng sâu/thường xuyên đến đâu','Cả hai chỉ đếm số tài khoản đăng ký mới','Retention đo thời lượng session còn engagement chỉ đo cohort quay lại'],'a','Retention là độ rộng quay lại; engagement là chiều sâu sử dụng.')
item(d,18,'Một authenticator được dùng đều nhưng mỗi lần rất ngắn có nhất thiết đang thất bại về engagement không?', ['Không; thời lượng ngắn có thể phù hợp nature của use case','Có; mọi sản phẩm phải kéo dài session mới tạo value','Có; retention cao không có ý nghĩa nếu không tăng screen time'],'a','Metric cần phản ánh việc hoàn thành job, không ép mọi sản phẩm theo cùng mức tương tác.')
item(d,21,'Nature và nurture khác nhau thế nào khi thiết kế quay lại sản phẩm?', ['Nature là nhịp nhu cầu vốn có; nurture là tác động nuôi/khuếch đại nhịp đó','Nurture tự tạo nhu cầu từ số không bất kể use case','Nature là lịch push mà đội marketing muốn gửi'],'a','Nhắc nhở nên bám nhu cầu có thật thay vì áp lịch chủ quan lên người dùng.')
item(d,22,'Một công cụ lập báo cáo hàng tháng nên kiểm tra nhịp quay lại theo cơ sở nào?', ['Chu kỳ công việc hàng tháng của người dùng','DAU chỉ vì coding copilot thường được dùng hàng ngày','Số notification tối đa hệ thống có thể gửi'],'a','Tần suất tự nhiên phụ thuộc job; ép daily có thể đo sai giá trị thật.')
item(d,23,'Hai segment có nhịp nhu cầu khác nhau. Chiến lược reminder phù hợp là gì?', ['Điều chỉnh theo nhịp từng segment','Gửi cùng tần suất cao nhất cho tất cả','Dùng nhịp trung bình để coi mọi người không quay lại đúng lịch là churn'],'a','Một lịch nhắc chung có thể hữu ích cho nhóm này nhưng làm phiền nhóm khác.')
item(d,25,'Định nghĩa active user nên xuất phát từ đâu?', ['Core action gần nhất với việc nhận value của use case','Mọi click để metric tăng nhanh hơn','Chỉ chọn DAU/MAU nào tạo con số lớn hơn'],'a','Đếm hoạt động có ý nghĩa cần nối metric với công việc và nhịp sử dụng thực.')
item(d,27,'Thứ tự nào phù hợp để chọn metric sản phẩm?', ['Use case → natural cadence → core action → ngưỡng active → metric','Metric phổ biến → gom thêm hành vi → suy ra use case','Mục tiêu báo cáo → chọn con số lớn → định nghĩa active sau'],'a','Metric cần được xây từ logic tạo giá trị thay vì chọn trước vì quen thuộc.')
item(d,29,'Retention cohort percentage giúp so sánh các cohort khác quy mô ban đầu bằng cách nào?', ['Chuẩn hóa người còn active theo tỷ lệ của cohort ban đầu','Cộng tất cả người active thành một tổng không chia cohort','Chỉ giữ số người còn lại tuyệt đối, bỏ mẫu số'],'a','Tỷ lệ cho thấy phần cohort còn lại tại cùng mốc thời gian, thay vì bị quy mô đăng ký chi phối.')
item(d,33,'Retention rất kém ngay từ đầu thường cần xem xét điều gì trước tối ưu bề mặt?', ['Core value, job, đối tượng hoặc trải nghiệm trung tâm có đúng không','Chỉ thêm popup quay lại mà giữ mọi giả định core value','Chỉ tăng acquisition để làm cohort cũ bớt nổi bật'],'a','Nếu giá trị cốt lõi chưa tồn tại thì các chỉnh nhỏ khó giải quyết lý do người dùng rời đi.')
item(d,38,'Thông báo push và cảm giác muốn tiến bộ thuộc hai loại trigger nào?', ['Push là external; mong muốn nội tại là internal','Push là internal; mong muốn tiến bộ là external','Cả hai đều là reward thay vì trigger'],'a','External đến từ tín hiệu bên ngoài; internal gắn trạng thái/cảm xúc bên trong người dùng.')
item(d,39,'Niềm vui làm chủ thử thách và thấy tiến bộ thuộc loại variable reward nào?', ['The Self','The Tribe: được cộng đồng công nhận','The Hunt: săn tài nguyên/thông tin'],'a','Self liên quan mastery/completion, khác phần thưởng xã hội hay tìm kiếm tài nguyên.')
item(d,44,'Gamification nên được đánh giá theo tiêu chí nào để hỗ trợ sản phẩm?', ['Có phục vụ core loop và hành vi tạo value không','Có đủ streak/leaderboard bất kể job của người dùng','Có làm tăng thao tác dù cản trở nhiệm vụ chính không'],'a','Cơ chế game chỉ hữu ích khi làm mạnh vòng giá trị thay vì thêm cản trở hoặc hoạt động rỗng.')
